module.exports = "<div class=\"bmb_filter_card\">\n  <ng-template #modalTemplate>\n    <div class=\"bmb_filter_card-modal\">\n      <form [formGroup]=\"filterForm\">\n        @if (showGlobalSearch()) {\n          <bmb-input\n            [placeholder]=\"placeholderSearch()\"\n            [icon]=\"'search'\"\n            [appearance]=\"'normal'\"\n            [control]=\"getFormControl('search')\"\n            [isClearable]=\"true\"\n          />\n        }\n        @for (controlType of controlTypes(); track $index) {\n          <h4 class=\"bmb_filter_card-title\">{{ controlType.title }}</h4>\n          <div class=\"bmb_filter_card-control\">\n            @for (control of controlType.control; track $index) {\n              @switch (control.type) {\n                @case ('tag') {\n                  <bmb-tag\n                    [text]=\"control.label\"\n                    [dismissible]=\"false\"\n                    [enableClick]=\"true\"\n                    [isActive]=\"storedValues[control.name]?.checked ?? false\"\n                    (clickedTag)=\"onControlChange(control, $event)\"\n                  />\n                }\n                @case ('radial') {\n                  <bmb-radial\n                    [name]=\"control.name\"\n                    [inputId]=\"control.id ?? control.name + '-' + $index\"\n                    [checked]=\"\n                      filterForm.get(control.name)?.value === control.label\n                    \"\n                    [label]=\"control.label\"\n                    (change)=\"onControlChange(control, $event)\"\n                    [value]=\"control.value ?? control.name\"\n                  />\n                }\n                @case ('checkbox') {\n                  <bmb-checkbox\n                    [name]=\"control.name\"\n                    [checked]=\"filterForm.get(control.name)?.value\"\n                    [label]=\"control.label\"\n                    (change)=\"onControlChange(control, $event)\"\n                    [inputId]=\"control.id ?? control.name + '-' + $index\"\n                    [value]=\"control.value ?? control.name\"\n                  />\n                }\n                @case ('switch') {\n                  <bmb-switch\n                    [rightText]=\"control.rightText ?? ''\"\n                    [isChecked]=\"filterForm.get(control.name)?.value === true\"\n                    (change)=\"onControlChange(control, $event)\"\n                  />\n                }\n                @case ('dropdown') {\n                  <bmb-dropdown\n                    [placeholder]=\"control.placeholder ?? ('filter_card.dropdown.placeholder')\"\n                    [options]=\"control.options ?? []\"\n                    [control]=\"getFormControl(control.type)\"\n                    (onValueChange)=\"onValueChange($event)\"\n                    [isFilterable]=\"true\"\n                  />\n                }\n              }\n            }\n          </div>\n        }\n        @if (inLine()) {\n          <footer class=\"bmb_filter_card-footer\">\n            <button bmbButton appearance=\"secondary-outlined\" type=\"reset\">\n              {{ secondaryBtnLabel() }}\n            </button>\n            <button bmbButton (click)=\"handleSubmit()\" type=\"submit\">\n              {{ primaryBtnLabel() }}\n            </button>\n          </footer>\n        }\n      </form>\n    </div>\n  </ng-template>\n\n  @if (inLine()) {\n    <ng-container [ngTemplateOutlet]=\"modalTemplate\" />\n  } @else {\n    <button\n      type=\"button\"\n      class=\"bmb_filter_card-button\"\n      (click)=\"openModalComponent()\"\n      type=\"button\"\n    >\n      <bmb-icon [icon]=\"icon()\" alt=\"Filter icon\" />\n    </button>\n  }\n</div>\n";

